function agregarPorMinuto(leituras) {
  const janelas = {}

  for (const leitura of leituras) {
    const valor = leitura.valor
    if (!Number.isFinite(valor)) continue

    const minuto = String(leitura.timestamp).slice(0, 16)
    const atual = janelas[minuto]

    if (!atual) {
      janelas[minuto] = { soma: valor, contagem: 1, media: valor, minimo: valor, maximo: valor }
      continue
    }

    atual.soma += valor
    atual.contagem += 1
    atual.media = atual.soma / atual.contagem
    atual.minimo = Math.min(atual.minimo, valor)
    atual.maximo = Math.max(atual.maximo, valor)
  }

  return janelas
}

