function combinarJanelas(janelas) {
  const validas = (janelas ?? []).filter((janela) => janela.contagem > 0)
  if (validas.length === 0) return null

  let soma = 0
  let contagem = 0
  let minimo = Infinity
  let maximo = -Infinity

  for (const janela of validas) {
    soma += janela.soma
    contagem += janela.contagem
    minimo = Math.min(minimo, janela.minimo)
    maximo = Math.max(maximo, janela.maximo)
  }

  return { soma, contagem, minimo, maximo, media: Math.round((soma / contagem) * 100) / 100 }
}

