function comandosParaEntregar(comandos, agora, jaExecutados) {
  const executados = new Set(jaExecutados ?? [])
  const instante = new Date(agora).getTime()

  return (comandos ?? []).filter((comando) => {
    if (comando.estado !== 'pendente') return false
    if (executados.has(comando.id)) return false
    return new Date(comando.expiraEm).getTime() > instante
  })
}

