function processarEventos(eventos) {
  const vistos = new Set()
  const processados = []
  const ignorados = []

  for (const evento of eventos) {
    // A identidade é o eventoId: dois eventos sobre o mesmo pedido são dois trabalhos.
    if (vistos.has(evento.eventoId)) {
      ignorados.push(evento.eventoId)
      continue
    }

    vistos.add(evento.eventoId)
    processados.push(evento.pedidoId)
  }

  return { processados, ignorados }
}
